// Etapa 1: so execucoes com erro disparadas por formulario/webhook real (mode = webhook; execucoes
// manuais, de teste e via MCP ficam de fora), das ultimas 26h, ainda nao registradas na aba de controle.
const JANELA_H = 26;
const lista = $('A03_lista_execucoes_erro').first().json.data || [];
const controle = $('A04_le_controle').first().json.values || [];
const registradas = new Set(controle.slice(1).map(r => String(r[0] || '')));
const limite = Date.now() - JANELA_H * 3600 * 1000;
return lista
  .filter(e => e.mode === 'webhook' && Date.parse(e.startedAt) >= limite && !registradas.has(String(e.id)))
  .map(e => ({ json: { execution_id: String(e.id), erro_em: e.startedAt } }));

const COLS = ["execution_id", "detectado_em", "erro_em", "razao_social", "cnpj", "email", "lead_id", "no_erro", "mensagem_erro", "causa", "status", "tentativas", "ultima_tentativa_em", "resultado_ultima_tentativa", "resend_email_id", "reenvio_execution_id", "observacao", "payload_json"];
const ROTULO = {
  cota_resend: 'Cota diária do Resend',
  rede: 'Rede / conexão (ECONNRESET)',
  rate_limit: 'Rate limit',
  schema_cache: 'Schema em cache (colunas do Sheets)',
  cnpj_invalido: 'CNPJ inválido',
  nao_identificada: 'Causa não identificada',
};
const dig = s => String(s || '').replace(/\D/g, '');
function sucessoPosterior(bf, leadId, cnpj, erroEm) {
  const hdr = bf[0] || [];
  const cLead = hdr.indexOf('lead_id'), cCnpj = hdr.indexOf('cnpj');
  const cStatus = hdr.lastIndexOf('status_funil'), cEnvio = hdr.indexOf('data_envio_proposta');
  return bf.slice(1).some(l => {
    const mesmo = (leadId && String(l[cLead] || '') === leadId) || (cnpj && dig(l[cCnpj]) === cnpj);
    return mesmo && String(l[cStatus] || '') === 'Proposta Enviada' && Date.parse(l[cEnvio] || '') > Date.parse(erroEm);
  });
}

const RETENTAVEL = { cota_resend: true, rede: true, rate_limit: true, nao_identificada: true, schema_cache: false, cnpj_invalido: false };
function classifica(msg, desc, no) {
  const t = (msg + ' ' + desc).toLowerCase();
  if (t.includes('daily email sending quota') || (t.includes('quota') && t.includes('email'))) return 'cota_resend';
  if (t.includes('column names were updated') || t.includes('schema cache')) return 'schema_cache';
  if (t.includes('too many requests') || t.includes('rate limit') || /\b429\b/.test(t)) return 'rate_limit';
  if (/econnreset|etimedout|econnrefused|socket hang up|eai_again|enotfound|connection to the server was closed|timed out|timeout/.test(t)) return 'rede';
  if (t.includes('cnpj') || no === '03_valida_cnpj' || no === '04_if_cnpj_ativo') return 'cnpj_invalido';
  return 'nao_identificada';
}
function saida(rd, no) { try { return rd[no][0].data.main[0][0].json; } catch (e) { return null; } }

const controle = $('A04_le_controle').first().json.values || [];
const registradas = new Set(controle.slice(1).map(r => String(r[0] || '')));
const bf = $('A05_le_base_funil').first().json.values || [];
const agora = new Date().toISOString();

const linhas = [];
for (const it of $input.all()) {
  const d = it.json;
  if (!d || !d.id || !d.data) continue;
  const r = d.data.resultData || {};
  const rd = r.runData || {};
  const payload = saida(rd, '00_normaliza_entrada') || saida(rd, '01_form_trigger');
  const razao = String((payload && payload['Razão Social']) || '').trim();
  // ruido de teste
  if (/^zz[_ ]/i.test(razao) || /teste/i.test(razao)) continue;
  // falha de um reenvio feito por este monitor: ja acompanhada na linha original
  if (payload && payload.reenvio_ref && registradas.has(String(payload.reenvio_ref))) continue;
  const err = r.error || {};
  const no = String(r.lastNodeExecuted || (err.node && err.node.name) || '');
  const msg = String(err.message || '');
  const desc = String(err.description || '');
  const norm = saida(rd, '02_normalizacao_lead') || {};
  // lead_id do lead criado na propria execucao que falhou: sem ele o reenvio criaria lead duplicado
  const leadId = String(norm.lead_id || (payload && payload.lead_id) || '');
  const cnpj = dig((payload && payload['CNPJ']) || norm.cnpj);
  const email = String((payload && payload['E-mail']) || norm.email || '');
  const envio = saida(rd, '18_email_proposta');
  const propostaEntregue = !!(envio && envio.id);
  const causa = classifica(msg, desc, no);
  let status, obs;
  if (sucessoPosterior(bf, leadId, cnpj, d.startedAt)) {
    status = 'resolvido_automaticamente'; obs = 'base_funil_completo mostra Proposta Enviada depois do erro.';
  } else if (propostaEntregue) {
    status = 'revisao_manual'; obs = 'Proposta ja entregue ao cliente (18_email_proposta ok); falha depois do envio, em ' + no + '. Nao reenviar.';
  } else if (!payload) {
    status = 'revisao_manual'; obs = 'Execucao sem dados de entrada: nao ha o que reenviar.';
  } else if (!RETENTAVEL[causa]) {
    status = 'revisao_manual'; obs = 'Causa nao se resolve com reenvio (' + ROTULO[causa] + ').';
  } else {
    status = 'pendente'; obs = 'Reenvio automatico as 21h.';
  }
  linhas.push({
    execution_id: String(d.id), detectado_em: agora, erro_em: d.startedAt, razao_social: razao, cnpj, email,
    lead_id: leadId, no_erro: no, mensagem_erro: (msg + (desc ? ' | ' + desc : '')).slice(0, 500), causa, status,
    tentativas: 0, ultima_tentativa_em: '', resultado_ultima_tentativa: '', resend_email_id: '', reenvio_execution_id: '',
    observacao: obs, payload_json: payload ? JSON.stringify({ ...payload, lead_id: leadId }) : '',
  });
}
if (!linhas.length) return [];

const EMOJI = { pendente: ':hourglass_flowing_sand:', revisao_manual: ':warning:', resolvido_automaticamente: ':white_check_mark:' };
const TXT = { pendente: 'pendente, reenvio automatico as 21h', revisao_manual: '*REVISAO MANUAL*', resolvido_automaticamente: 'ja resolvida (proposta enviada depois)' };
const texto = ':rotating_light: *Monitor de propostas: ' + linhas.length + ' falha(s) nova(s) em Geracao de Proposta*\n' +
  linhas.map(l => EMOJI[l.status] + ' *' + (l.razao_social || '(sem razao social)') + '*: ' + ROTULO[l.causa] + ' em `' + l.no_erro + '`, ' + TXT[l.status] +
    (l.status === 'revisao_manual' ? '\n      ' + l.observacao : '') +
    '\n      ' + 'https://raregoat-n8n.cloudfy.live/workflow/EQ3YEDcPysyaFlZp/executions/' + l.execution_id).join('\n');
return [{ json: { total: linhas.length, registros: linhas, valores: linhas.map(l => COLS.map(c => l[c] === undefined ? '' : l[c])), slack_texto: texto } }];

const COLS = ["execution_id", "detectado_em", "erro_em", "razao_social", "cnpj", "email", "lead_id", "no_erro", "mensagem_erro", "causa", "status", "tentativas", "ultima_tentativa_em", "resultado_ultima_tentativa", "resend_email_id", "reenvio_execution_id", "observacao", "payload_json"];
const ROTULO = {
  cota_resend: 'Cota diária do Resend',
  rede: 'Rede / conexão (ECONNRESET)',
  rate_limit: 'Rate limit',
  schema_cache: 'Schema em cache (colunas do Sheets)',
  cnpj_invalido: 'CNPJ inválido',
  nao_identificada: 'Causa não identificada',
};
const dig = s => String(s || '').replace(/\D/g, '');
function sucessoPosterior(bf, leadId, cnpj, erroEm) {
  const hdr = bf[0] || [];
  const cLead = hdr.indexOf('lead_id'), cCnpj = hdr.indexOf('cnpj');
  const cStatus = hdr.lastIndexOf('status_funil'), cEnvio = hdr.indexOf('data_envio_proposta');
  return bf.slice(1).some(l => {
    const mesmo = (leadId && String(l[cLead] || '') === leadId) || (cnpj && dig(l[cCnpj]) === cnpj);
    return mesmo && String(l[cStatus] || '') === 'Proposta Enviada' && Date.parse(l[cEnvio] || '') > Date.parse(erroEm);
  });
}

const MAX_TENTATIVAS = 3, MAX_DIAS = 3;
const vals = $('B03_le_controle').first().json.values || [];
const H = vals[0] || [];
const rows = vals.slice(1).map((v, i) => { const o = { linha: i + 2 }; H.forEach((h, j) => { o[h] = v[j] === undefined ? '' : v[j]; }); return o; });
const bf = $('B04_le_base_funil').first().json.values || [];
const inicio = new Date().toISOString();
const pend = rows.filter(r => r.status === 'pendente');
if (!pend.length) return [];
// mesmo lead (CNPJ ou e-mail) com mais de uma falha pendente: so a mais recente e reenviada
const grupos = {};
for (const r of pend) { const k = r.cnpj || r.email || r.execution_id; (grupos[k] = grupos[k] || []).push(r); }
const out = [];
for (const g of Object.values(grupos)) {
  g.sort((a, b) => Date.parse(b.erro_em) - Date.parse(a.erro_em));
  g.forEach((r, i) => {
    const dias = (Date.now() - Date.parse(r.erro_em)) / 86400000;
    const tent = Number(r.tentativas || 0);
    let acao;
    if (sucessoPosterior(bf, r.lead_id, r.cnpj, r.erro_em)) acao = 'resolver';
    else if (i > 0) acao = 'substituir';
    else if (tent >= MAX_TENTATIVAS || dias >= MAX_DIAS) acao = 'escalar';
    else acao = 'reenviar';
    out.push({ json: { ...r, acao, substituida_por: i > 0 ? g[0].execution_id : '', inicio_rodada: inicio } });
  });
}
return out;

const atual = $('B07_if_reenviar').first().json;
const post = $('B08_post_webhook').first().json;
const alvo = ($json.data || []).find(e => {
  try { return e.data.resultData.runData['00_normaliza_entrada'][0].data.main[0][0].json.reenvio_ref === atual.execution_id; }
  catch (x) { return false; }
});
let emailId = '', statusExec = '', erroExec = '';
if (alvo) {
  statusExec = alvo.status;
  try { emailId = alvo.data.resultData.runData['18_email_proposta'][0].data.main[0][0].json.id || ''; } catch (x) {}
  const er = alvo.data.resultData.error || {};
  erroExec = String(er.message || '') + (er.description ? ' | ' + er.description : '');
}
return [{ json: { ...atual, http_webhook: post.statusCode, reenvio_execution_id: alvo ? String(alvo.id) : '',
  status_execucao: statusExec, erro_execucao: erroExec, resend_email_id: emailId } }];

const a = $('B11_localiza_reenvio').first().json;
const ev = ($json.body && $json.body.last_event) || '';
let status = 'pendente', resultado;
if (a.http_webhook !== 202) resultado = 'webhook respondeu HTTP ' + a.http_webhook;
else if (!a.reenvio_execution_id) resultado = 'execucao do reenvio nao localizada em 90s';
else if (a.status_execucao !== 'success') resultado = 'reenvio falhou de novo (' + a.status_execucao + '): ' + String(a.erro_execucao).slice(0, 300);
else if (!a.resend_email_id) resultado = 'execucao ' + a.reenvio_execution_id + ' terminou sem e-mail de proposta';
else if (ev === 'delivered') { status = 'reenviado'; resultado = 'delivered (Resend)'; }
else { status = 'reenviado'; resultado = 'enviado; entrega ainda nao confirmada no Resend (last_event=' + (ev || 'desconhecido') + ')'; }
return [{ json: { ...a, status, tentativas: Number(a.tentativas || 0) + 1, ultima_tentativa_em: new Date().toISOString(), resultado_ultima_tentativa: resultado } }];

const a = $json;
const MAPA = {
  resolver: ['resolvido_automaticamente', 'base_funil_completo mostra Proposta Enviada depois do erro'],
  substituir: ['substituido', 'Ha falha mais recente do mesmo lead (execucao ' + a.substituida_por + '); so ela e reenviada'],
  escalar: ['revisao_manual', 'Limite atingido (' + Number(a.tentativas || 0) + ' tentativa(s); erro em ' + a.erro_em + '): escalado para revisao manual'],
};
const [status, resultado] = MAPA[a.acao];
return [{ json: { ...a, status, ultima_tentativa_em: new Date().toISOString(), resultado_ultima_tentativa: resultado } }];

const inicio = $('B05_seleciona').first().json.inicio_rodada;
const vals = $json.values || [];
const H = vals[0] || [];
const rows = vals.slice(1).map(v => { const o = {}; H.forEach((h, j) => { o[h] = v[j] === undefined ? '' : v[j]; }); return o; });
const mexidas = rows.filter(r => r.ultima_tentativa_em && r.ultima_tentativa_em >= inicio);
if (!mexidas.length) return [];
const GRUPOS = [
  ['reenviado', ':white_check_mark: Reenviadas'],
  ['pendente', ':repeat: Reenvio falhou, nova tentativa amanha'],
  ['revisao_manual', ':warning: Escaladas para revisao manual'],
  ['resolvido_automaticamente', ':ballot_box_with_check: Ja resolvidas (proposta enviada depois)'],
  ['substituido', ':arrow_right_hook: Substituidas por falha mais recente do mesmo lead'],
];
let texto = ':outbox_tray: *Monitor de propostas: resumo do reenvio das 21h (' + mexidas.length + ' registro(s))*';
for (const [st, titulo] of GRUPOS) {
  const g = mexidas.filter(r => r.status === st);
  if (!g.length) continue;
  texto += '\n' + titulo + ':\n' + g.map(r => '   - *' + (r.razao_social || '(sem razao social)') + '*: ' + r.resultado_ultima_tentativa +
    (r.reenvio_execution_id ? ' (execucao ' + r.reenvio_execution_id + ')' : '')).join('\n');
}
return [{ json: { total: mexidas.length, slack_texto: texto } }];
